from pathlib import Path
import os,subprocess,json,urllib.request,urllib.parse,ssl
R=Path('/root/csi-lab');os.environ['KUBECONFIG']=str(R/'kubeconfig')
def facts():return json.loads((R/'cluster-access.json').read_text())
def node(vmid,code):
 v=facts()[str(vmid)];guard='set -euo pipefail\ntest "$(cat /sys/class/dmi/id/product_uuid)" = "'+v['uuid']+'"\ntest "$(hostname -s)" = "'+v['name']+'"\n'
 p=subprocess.run(['ssh','-i',str(R/'id_ed25519'),'-o','IdentitiesOnly=yes','-o','BatchMode=yes','-o','StrictHostKeyChecking=yes','-o','UserKnownHostsFile='+str(R/'cluster-known-hosts'),'csi-lab@'+v['ip'],'sudo','-n','bash','-s'],input=guard+code,text=True,capture_output=True,timeout=240)
 if p.returncode:raise RuntimeError(v['name']+': '+p.stderr[-2000:])
 return p.stdout
def api(method,path,params=None):
 a=json.loads((R/'tokens.json').read_text())['terraform'];data=None if params is None else urllib.parse.urlencode(params).encode()
 req=urllib.request.Request('https://10.9.9.20:8006/api2/json'+path,data=data,method=method,headers={'Authorization':'PVEAPIToken='+a['token_id']+'='+a['token_secret']})
 with urllib.request.urlopen(req,context=ssl._create_unverified_context(),timeout=45) as f:return json.load(f)['data']
def k(*args,input=None):return subprocess.check_output(['kubectl',*args],input=input,text=True,timeout=240)
def j(*args):return json.loads(k(*args,'-o','json'))
def probe():return json.loads(k('-n','csi-lab','exec','-i','deploy/sqlite','--','python','-','verify',input=(R/'sqlite-probe.py').read_text()))
def save(name,data):(R/'evidence'/name).write_text(json.dumps(data,indent=2)+'\n')

def volume():
 attachments=[]
 for vmid in [981,982,983]:
  c=api('GET',f'/nodes/pve/qemu/{vmid}/config')
  for key,val in c.items():
   if key.startswith('scsi') and isinstance(val,str) and val.startswith('csi-truenas-assessment:9980/vm-9980-lab.raw,'):attachments.append({'vmid':vmid,'slot':key,'config':val})
 assert len(attachments)==1,attachments
 a=attachments[0];d=json.loads(node(a['vmid'],'lsblk -J -o NAME,UUID,FSTYPE,MOUNTPOINTS\n'))
 disks=[x for x in d['blockdevices'] if x.get('fstype')=='ext4' and any(m and m.endswith('/globalmount') for m in x.get('mountpoints',[]))]
 assert len(disks)==1,disks
 return {'attachment':a,'filesystem':disks[0]}

