import json,subprocess,re,hashlib
from pathlib import Path
R=Path('/var/tmp/csi-tn-20261003');L=json.loads((R/'ledger.json').read_text());done=[]
def run(*a):return subprocess.check_output(list(a),text=True,stderr=subprocess.PIPE,timeout=180)
def get(p):return json.loads(run('pvesh','get',p,'--output-format','json'))
def record(kind,name):done.append({'type':kind,'name':name});(R/'cleanup-progress.json').write_text(json.dumps(done,indent=2)+'\n')
assert L['run']=='csi-tn-20261003';assert not any(v.get('vmid') in [981,982,983] for v in get('/cluster/resources'))
c=get('/nodes/pve/qemu/980/config');e=next(x for x in L['created'] if x.get('vmid')==980)['identity'];assert c['name']=='csi-lab-runner' and c['vmgenid']==e['vmgenid'] and c['smbios1']==e['smbios1']
for key in ['virtio0','ide0']:assert c[key].split(',')[0]==e[key].split(',')[0]
assert not any(re.match(r'^(scsi|sata|unused)\d+$',k) for k in c)
s=get('/storage/csi-truenas-assessment');assert s['server']=='10.9.9.30' and s['export']=='/mnt/apps/csi-qualification-20261003' and s['path']=='/mnt/pve/csi-truenas-assessment'
images={x['volid'] for x in L['created'] if x['type']=='image'};assert images=={'csi-truenas-assessment:9980/vm-9980-'+n+'.raw' for n in ['lab','blank','wrongtype']}
assert {x['volid'] for x in get('/nodes/pve/storage/csi-truenas-assessment/content')}==images
for vm in get('/cluster/resources'):
 if vm.get('type') in ['qemu','lxc']:
  conf=get('/nodes/'+vm['node']+'/'+vm['type']+'/'+str(vm['vmid'])+'/config');assert not any('csi-truenas-assessment:' in str(v) for v in conf.values())
users={x['name'] for x in L['created'] if x['type']=='user'};assert users=={'csi-tn-20261003@pve','tf-tn-20261003@pve'}
roles={x['name'] for x in L['created'] if x['type']=='role'};assert len(roles)==6 and all(x.startswith('CSITN') and x.endswith('20261003') for x in roles)
assert not any(x['roleid'] in roles and x['ugid'] not in users for x in get('/access/acl'));assert not get('/pools/csi-tn-20261003')['members']
for vol in sorted(images):run('pvesm','free',vol);record('image-deleted',vol)
assert not get('/nodes/pve/storage/csi-truenas-assessment/content')
run('pvesm','set','csi-truenas-assessment','--disable','1');run('umount','/mnt/pve/csi-truenas-assessment');run('pvesm','remove','csi-truenas-assessment');record('storage-removed','csi-truenas-assessment')
for user in sorted(users):run('pveum','user','delete',user);record('user-token-revoked',user)
assert not any(x['ugid'] in users for x in get('/access/acl'))
for role in sorted(roles):run('pveum','role','delete',role);record('role-removed',role)
run('pvesh','delete','/pools/csi-tn-20261003');record('pool-removed','csi-tn-20261003')
run('qm','stop','980');assert get('/nodes/pve/qemu/980/status/current')['status']=='stopped';run('qm','destroy','980','--purge','1');record('runner-and-disks-deleted','980')
assert not any(x.get('vmid') in [980,981,982,983,9980] for x in get('/cluster/resources'))
for store in ['vm-pool','local-zfs']:assert not any(x.get('vmid') in [980,981,982,983] for x in get('/nodes/pve/storage/'+store+'/content'))
assert not any(x.get('userid') in users for x in get('/access/users'));assert not any(x.get('roleid') in roles for x in get('/access/roles'))
assert not any(x.get('storage')=='csi-truenas-assessment' for x in get('/storage'))
assert subprocess.run(['mountpoint','-q','/mnt/pve/csi-truenas-assessment']).returncode!=0
p=Path('/mnt/pve/csi-truenas-assessment')
if p.is_dir():p.rmdir()
unchanged={}
for vmid,expected in L['production_config_hashes'].items():
 c=get('/nodes/pve/qemu/'+vmid+'/config');c.pop('digest',None);unchanged[vmid]=hashlib.sha256(json.dumps(c,sort_keys=True).encode()).hexdigest()==expected
assert all(unchanged.values()),unchanged
result={'proxmox_cleanup_complete':True,'removed':done,'all_lab_vms_disks_users_roles_acls_absent':True,'nfs_mount_absent':True,'production_vm_configs_unchanged':unchanged};L['cleanup']=result;(R/'ledger.json').write_text(json.dumps(L,indent=2)+'\n');(R/'cleanup.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
